import{_ as a,o as e,c as d,ak as s}from"./chunks/framework.DKi5cyCJ.js";const b=JSON.parse('{"title":"插补与速度规划","description":"路径插补与单轴速度表、Bresenham、节拍进给、前瞻三级；含动态演示","frontmatter":{"title":"插补与速度规划","description":"路径插补与单轴速度表、Bresenham、节拍进给、前瞻三级；含动态演示","date":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-21-插补与速度规划.md","filePath":"pages/blog/2026-10-21-插补与速度规划.md"}'),r={name:"pages/blog/2026-10-21-插补与速度规划.md"};function n(o,t,h,l,p,i){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="插补与速度规划" tabindex="-1">插补与速度规划 <a class="header-anchor" href="#插补与速度规划" aria-label="Permalink to &quot;插补与速度规划&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a>。任务划分见 <a href="/pages/blog/2026-10-21-RTOS线程与多轴.html">RTOS 线程与多轴</a>。<br><strong>动态演示</strong>（必看）：<a href="/demos/interp-demo.html" target="_blank">插补 · 速度表 · 节拍进给 · 前瞻</a></p></blockquote><div class="blog-demo-frame blog-demo-frame--tall"><iframe src="/demos/interp-demo.html?embed=1" title="插补与速度规划动态演示" loading="lazy"></iframe></div><p>步进电机只认脉冲。数控意义上的<strong>路径插补</strong>决定多轴如何走出直线/圆弧；<strong>单轴速度规划</strong>决定一根轴如何 Acc→Const→Dec。口语里有人把「刷新脉冲周期」也叫插补——那是速度层。本文按数控标准区分二者。</p><h2 id="两类不要混" tabindex="-1">两类不要混 <a class="header-anchor" href="#两类不要混" aria-label="Permalink to &quot;两类不要混&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>解决什么</th><th>典型算法</th><th>现网 MCU 直驱</th></tr></thead><tbody><tr><td>轨迹 / 路径插补</td><td>多轴同步走出直线、圆弧</td><td>Bresenham、DDA</td><td><strong>无</strong></td></tr><tr><td>速度 / 脉冲时序</td><td>单轴从静止加速到巡航再减速</td><td>梯形/S 曲线、速度表</td><td><strong>有</strong></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>路径插补：目标路径 → 每周期各轴 Δpulse → 各轴发脉冲</span></span>
<span class="line"><span>单轴速度：目标步数 → Acc/Const/Dec → TIM 改 ARR → STEP</span></span></code></pre></div><p>现网直驱常见路径：应用命令 → 速度表 + 相位机 → ISR 改 ARR → DRV8711。表值近似微步 pps；短行程会裁剪加减速段。多电机是命令级串行/并行 + 各轴独立 TIM——「推手与盘同时动」是调度并行，<strong>不等于</strong>路径插补。</p><h2 id="什么时候才需要真正的插补" tabindex="-1">什么时候才需要真正的插补 <a class="header-anchor" href="#什么时候才需要真正的插补" aria-label="Permalink to &quot;什么时候才需要真正的插补&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>要不要路径插补</th></tr></thead><tbody><tr><td>推手到坐标 / 相对步进 / 盘到工位</td><td>否（单轴点到点 + 速度表）</td></tr><tr><td>推手与盘「一起动」</td><td>否（并行，非联动轨迹）</td></tr><tr><td>两直线轴必须走出斜线/平面直线</td><td><strong>是</strong></td></tr><tr><td>平面圆弧、复杂轮廓</td><td><strong>是</strong></td></tr></tbody></table><p>盘电机转到下一孔，物理上走过圆弧，控制上只有 θ 一维。走圆弧形机构 ≠ 软件圆弧插补。</p><p><strong>落地判断</strong>：只有产品要求「两个及以上自由度在运动中必须满足几何比例/曲线」，才上路径插补。</p><h2 id="bresenham-直线" tabindex="-1">Bresenham 直线 <a class="header-anchor" href="#bresenham-直线" aria-label="Permalink to &quot;Bresenham 直线&quot;">​</a></h2><p>假想 X、Z 从 A 到 B 必须沿斜线（不能先抬后移）。若仍发两次独立 Move，空间轨迹不是直线 AB。</p><p>第一象限且 X 为主轴（dx ≥ dy ≥ 0）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>err = 2*dy - dx</span></span>
<span class="line"><span>重复 dx 次：</span></span>
<span class="line"><span>  发一步 X</span></span>
<span class="line"><span>  若 err &gt; 0：发一步 Y，err = err + 2*dy - 2*dx</span></span>
<span class="line"><span>  否则：err = err + 2*dy</span></span></code></pre></div><p>(10,3) 初始误差 -4，Y 的 3 步摊在 10 步 X 里，偏差不超过半步。DDA 用累加器溢出，多轴和圆弧更直接。量产通常是：路径插补器 → 各轴速度整形 → 脉冲发生器；现网只有后半。</p><h2 id="节拍-δn-n-条短-move" tabindex="-1">节拍 ΔN ≠ N 条短 Move <a class="header-anchor" href="#节拍-δn-n-条短-move" aria-label="Permalink to &quot;节拍 ΔN ≠ N 条短 Move&quot;">​</a></h2><p>插补节拍（如 1 kHz）只负责「这一小段时间各轴该分多少脉冲」。整段轨迹共用<strong>一条</strong>进给速度曲线，拍与拍首尾相接。</p><table tabindex="0"><thead><tr><th></th><th>N 条短 Move</th><th>插补 + 一条 F(t)</th></tr></thead><tbody><tr><td>启停</td><td>每条都可能 Acc/Dec</td><td>整段只加减速一次</td></tr><tr><td>体感</td><td>一顿一顿</td><td>一条连续斜线</td></tr></tbody></table><p>T=1 ms、某拍 ΔN=20 → 约 20000 pps；下一拍继续，不回到 0。粗插补在 MotionTask，精插补由定时器均匀发 STEP。浮点规划不要放进定时器中断。</p><h2 id="前瞻-look-ahead" tabindex="-1">前瞻 Look-ahead <a class="header-anchor" href="#前瞻-look-ahead" aria-label="Permalink to &quot;前瞻 Look-ahead&quot;">​</a></h2><p>插补管一段路径内怎么分脉冲；前瞻管多段首尾相接时拐角要不要每次刹到 0。</p><table tabindex="0"><thead><tr><th>级别</th><th>段边界</th><th>适合</th></tr></thead><tbody><tr><td>0</td><td>每段减速到 0</td><td>定位、注射泵、转盘。现网常态</td></tr><tr><td>1</td><td>固定或查表衔接速度</td><td>曲率变化不大的连续轨迹</td></tr><tr><td>2</td><td>曲率约束 + 双向传播</td><td>数控、切割</td></tr></tbody></table><p>现网单段 Move / 盘 goto 段末本要停稳；时序命令之间常有业务等待。只有「连续折线且不允许段段停稳」时才谈前瞻。</p><p>三层速记：① 路径插补（现网无）② 单段速度规划（现网有）③ 多段前瞻（现网用不上）。急停独立于前瞻，见 <a href="/pages/blog/2026-10-21-RTOS线程与多轴.html">RTOS 线程与多轴</a>。</p><p><a href="/demos/interp-demo.html" target="_blank">打开动态演示</a> · <a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>`,27)])])}const g=a(r,[["render",n]]);export{b as __pageData,g as default};
